//! Actions-only SAME original SDK and auxiliary TCP/TLS/Common ownership.
//! Real prefix acceptance, current IM replies, global accounting, cancelled
//! query and unhosting/logout/relay/IO Join; no original lib/device execution.
use super::*;
use super::super::super::super as n;
use std::sync::atomic::Ordering;
async fn bounded<F:std::future::Future>(work:F)->F::Output{tokio::time::timeout(Duration::from_secs(12),work).await.expect("original physical fixture budget")}
fn refresh_result()->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(0).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn scenario(mode:u8){
    let cert=Certificates::generate("IP:127.0.0.1");let front=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=front.local_addr().unwrap().port();let boot=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let main=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let aux=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let ports=[boot.local_addr().unwrap().port(),main.local_addr().unwrap().port(),aux.local_addr().unwrap().port()];let server=cert.server_config(&TLS13);let source_server=server.clone();let main_server=server.clone();
    let relay=tokio::spawn(async move{bounded(async move{let mut joins=Vec::new();for target in ports{let(mut incoming,_)=front.accept().await.unwrap();let mut outgoing=tokio::net::TcpStream::connect((std::net::Ipv4Addr::LOCALHOST,target)).await.unwrap();joins.push(tokio::spawn(async move{let _=tokio::io::copy_bidirectional(&mut incoming,&mut outgoing).await;}));}for join in joins{join.await.unwrap();}}).await});
    let source=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(boot,source_server).await;let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,b"getAppConfigs.AccountEntry.Account");peer.send(&[reply(r.call_id,&bootstrap_user_entry())]).await;peer.no_more_common().await;}).await});
    let sdk=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(main,main_server).await;let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,b"loginSession.AccountEntry.Account");peer.send(&[reply(r.call_id,&login_result())]).await;let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"4");for _ in 0..4{let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::im_status::REFRESH_METHOD.as_bytes());assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");assert_eq!(r.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");peer.send(&[reply(r.call_id,&refresh_result())]).await;}let(_,flag)=hosting_call(&mut peer).await;assert_eq!(flag,b"3");logout_peer(peer).await;}).await});
    let resolver=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(aux,server).await;assert!(peer.next().await.is_none(),"partial ciphertext cannot complete or replay an auxiliary business RPC");}).await});
    let receivers=n::native_receiver::NativeReceiverConfig{direct_domains:None,invite_notifications:None,im_messages:Some(n::im_delivery::NativeImConfig{notification_timeout_ms:3000})};let p=RuntimeProfile::supplied_common_bootstrap(bootstrap_inputs(),bootstrap_common(&cert.root,port),bootstrap_route()).unwrap().with_native_receivers(Some(&receivers)).unwrap().with_client_ex(true).unwrap();let denied=Arc::new(LegacyDenied{calls:AtomicUsize::new(0)});let(backend,mut events)=NativeHostingBackend::new(p,denied.clone());let who=owner();backend.login(who.clone(),SdkLoginRequest{server_address:BOOTSTRAP_SDK,..request(&cert.root)}).await.unwrap();let parent=backend.original_scope(&who).unwrap();backend.pause_original_polls_for_test(&who,&parent,true).unwrap();let e=bounded(events.recv()).await.unwrap();assert!(matches!(e.payload,BackendEventPayload::Callback(c)if c.callback==(Callback::SdkLogin{success:true})));backend.update_status(who.clone(),STATUS_REGISTER,gateway()).await.unwrap();let attempt=backend.original(&who).unwrap();let commands=attempt.commands(&who,&parent).unwrap();let gate=ImReceiptGate::fresh();let mut retained=Vec::new();for _ in 0..4{let q=Arc::new(n::rpc_im::ImQuery::refresh(&[],-1).unwrap());retained.push(commands.read_im(&who,&parent,q,gate.clone()).await.unwrap());}assert_eq!(parent.native_rpc_resources().0,4);
    let control=n::router_runtime::tests::auxiliary_io::AuxiliaryIoTest::original(if mode==0{0}else{1});let action=UserEntryAction::original(who.clone(),parent.clone(),gate.clone(),Instant::now()+Duration::from_secs(3),b"[phone:+12345@account-domain.invalid]").unwrap();action.set_auxiliary_io_test(control.clone());let mut lookup=Box::pin(backend.resolve_user_entry(action));bounded(async{tokio::select!{_=control.paused()=>(),r=&mut lookup=>panic!("query returned before the original physical prefix pause: {r:?}")}}).await;let child=control.scope();assert!(!child.matches(&parent));assert!(child.is_open());assert_eq!(control.accepted.load(Ordering::SeqCst),usize::from(mode!=0));assert!(control.pauses.load(Ordering::SeqCst)>0);assert!(tokio::time::timeout(Duration::from_millis(35),&mut lookup).await.is_err());assert_eq!(parent.native_rpc_resources().0,5);assert_eq!(attempt.user_entries.active(),1);
    // Real original IM replies + pending physical auxiliary + local resource
    // reservations fill one existing 128-entry bound, not separate per-engine
    // maxima. A refused Group query never consumes a physical SDK RPC frame.
    let mut pressure=Vec::new();for _ in 0..123{pressure.push(parent.reserve_native_rpc(1).unwrap());}assert_eq!(parent.native_rpc_resources().0,128);assert_eq!(commands.read_im(&who,&parent,Arc::new(n::rpc_im::ImQuery::refresh(&[],-1).unwrap()),gate.clone()).await.err(),Some(n::transport_actor::RuntimeError::InvalidConfiguration));assert!(parent.is_open());drop(pressure);
    if mode==2{gate.retire();assert_eq!(bounded(lookup).await.err(),Some("app_account_user_entry_scope_invalid"));}else if mode==3{let stop=backend.update_status(who.clone(),STATUS_UNREGISTER,gateway());let(query,stop)=bounded(async{tokio::join!(lookup,stop)}).await;assert_eq!(query.err(),Some("app_account_user_entry_scope_invalid"));stop.unwrap();}else{drop(lookup);}
    assert!(!child.is_open());assert!(control.dropped.load(Ordering::SeqCst),"same physical owner drops before its book slot is released");assert_eq!(attempt.user_entries.active(),0);assert_eq!(attempt.user_entries.retained_bytes(),0);assert_eq!(parent.native_rpc_resources().0,4);assert!(parent.is_open());drop(retained);assert_eq!(parent.native_rpc_resources(),(0,0));assert_eq!(denied.calls.load(Ordering::SeqCst),0);if mode!=3{backend.update_status(who.clone(),STATUS_UNREGISTER,gateway()).await.unwrap();}backend.logout(who).await.unwrap();assert!(lock(&attempt.state).released);assert!(!parent.is_open());bounded(async{source.await.unwrap();sdk.await.unwrap();resolver.await.unwrap();relay.await.unwrap();}).await;
}
#[tokio::test]async fn native_budget_auxiliary_queued_physical_no_bytes_cancel_keeps_original_sdk_and_all_joins(){Box::pin(scenario(0)).await;}
#[tokio::test]async fn native_budget_auxiliary_actual_partial_ciphertext_cancel_reclaims_only_original_auxiliary_io(){Box::pin(scenario(1)).await;}
#[tokio::test]async fn native_budget_auxiliary_partial_parent_gate_retirement_keeps_same_resource_accounting_and_joins(){Box::pin(scenario(2)).await;}
#[tokio::test]async fn native_budget_auxiliary_partial_stop_waits_for_fd_drop_before_original_unhosting_and_logout(){Box::pin(scenario(3)).await;}
